// === Tab: mySketch ===
// Attractor_24.0

let N = 100 ; let M = 100 ; let RR = 300 ; 

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let R ; let A ; let I ; let II ; let Q ; let QQ ; let P ; let PP ; let S ; let SS ;
let cosS ; let sinS ; let cosSS ; let sinSS ;

function setup(){
  createCanvas(600, 600) ; background(0) ;
  fill(0,0,0,10) ; stroke(255,0,0) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(-300,+300) ; Y[I] = random(-300,+300) ;
  }//let Q = sqrt(2) ; QQ = RR/Q ; P = random(0,PI) ; PP = random(0,PI) ; S = random(0,PI) ; SS = random(0,PI) ;
}//setup()

function draw(){
  rect(0,0,599,599) ;
	cosS = cos(S) ; sinS = sin(S) ; cosSS = cos(SS) ; sinSS = sin(SS) ;
  for ( I = 0 ; I < N ; I++ ){
		for ( II = 0 ; II < M ; II++ ){
			if ( X[I] > 0 ){
				A = atan(Y[I]/X[I]) ;
				R = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
				A = A*2 + P ; R = R/Q ;
				X[I] = R*cos(A) - (QQ*cosS) ;
				Y[I] = R*sin(A) - (QQ*sinS) ;
			}else{
				A = atan(Y[I]/X[I]) ;
				R = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
				A = A*2 + PP ; R = R/Q ;
				X[I] = R*cos(A) + (QQ*cosSS) ;
				Y[I] = R*sin(A) + (QQ*sinSS) ;
			}
      point(X[I]+300,Y[I]+300) ; 
		}//II
		if( R > 30000 ){ X[I] = random(-300,+300) ; Y[I] = random(-300,+300) ; }
  }//let P = P + 0.0003 ; PP = PP + 0.0005 ; S = S + 0.0007 ; SS = SS + 0.0011 ;
}//draw()

function mousePressed(){ setup() ; }

